import bounds from '../assets/enemies/bounds-v1.json' with {type:'json'};
import portraits from '../assets/enemies/portraits-v1.json' with {type:'json'};
import chapterTwo from '../assets/enemies/chapter2/bounds-v2.json' with {type:'json'};
import {ENEMIES} from './enemy-roster.mjs';
const intro={M01:'近身双钳与尾刺，留意蓄力后的突袭。',M02:'前足连刺，持续追击靠近的旅者。',M03:'在空中追击，收翼后俯冲撕咬。',M04:'举起重锤后猛砸，收招时有反击机会。',M05:'移动灵活，双镰接连切入近身。',M06:'盾击后接短剑刺，适合拉开距离。',M07:'保持距离口喷毒液，毒池会持续伤害。',M08:'抛射毒囊，在落点留下危险区域。',M09:'从远处投射暗羽，利用平台避开弹道。',M10:'钩斧近战与锁链远投交替施压。'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function enemyPortraitRect(id){const authored=chapterTwo.units[id];if(authored)return {file:authored.file,size:authored.size,frame:authored.portrait.frame,rect:authored.portrait.rect};const m=bounds.units[id],p=portraits.units[id];if(!m||!p)return null;const f=m.frames[p.frame].rect,[x,y,width,height]=p.rect;return {file:m.file,size:m.size,frame:p.frame,rect:[f[0]+x,f[1]+y,width,height]};}
export function enemyPortraitStyle(id){const p=enemyPortraitRect(id);if(!p)return '';const [x,y,width,height]=p.rect;return `background-image:url('assets/enemies/${p.file}');background-size:${p.size[0]/width*100}% ${p.size[1]/height*100}%;background-position:${x/(p.size[0]-width)*100}% ${y/(p.size[1]-height)*100}%`;}
export function renderEncounterCards(stage){const card=(id,boss=false)=>{const d=ENEMIES[id],copy=d.boss?(d.passiveText||d.trait):intro[id]||d.trait||'观察蓄力与出招，避开危险落点。';return `<button class="encounter-card has-tip ${boss?'encounter-boss':''}" data-tip="${escape(d.name+'：'+copy)}" aria-label="${escape(d.name)}，查看简介"><i class="enemy-portrait" style="${enemyPortraitStyle(id)}"></i><strong>${d.name}</strong></button>`;};return `<section class="encounter-boss-group"><small>守关首领</small>${(stage.bosses||[stage.boss]).map(id=>card(id,true)).join('')}</section><section class="encounter-minions"><small>本关妖兽</small><div>${card(stage.melee)}${card(stage.ranged)}</div></section>`;}
